    23	/// [`build`] helper consumes it so all commands route through
    24	/// identical filter semantics.
    25	pub struct FilterInputs<'a> {
    26	    pub include: &'a [String],
    27	    pub exclude: &'a [String],
    28	    pub files_from: Option<&'a PathBuf>,
    29	    /// ssc-6: an in-memory exact-path set (the previous pass's failed
